package com.axion.mlbb.service`n`nimport android.app.Service`nimport android.content.Intent`nimport android.graphics.PixelFormat`nimport android.os.IBinder`nimport android.view.Gravity`nimport android.view.MotionEvent`nimport android.view.View`nimport android.view.WindowManager`nimport android.widget.Button`n`nclass FloatingOverlayService : Service() {`n    private lateinit var windowManager: WindowManager`n    private lateinit var floatingButton: Button`n    private lateinit var params: WindowManager.LayoutParams`n`n    override fun onBind(intent: Intent?): IBinder? = null`n`n    override fun onCreate() {`n        super.onCreate()`n        windowManager = getSystemService(WINDOW_SERVICE) as WindowManager`n        params = WindowManager.LayoutParams(`n            WindowManager.LayoutParams.WRAP_CONTENT,`n            WindowManager.LayoutParams.WRAP_CONTENT,`n            WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,`n            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,`n            PixelFormat.TRANSLUCENT`n        ).apply {`n            gravity = Gravity.TOP or Gravity.START`n            x = 100`n            y = 100`n        }`n`n        floatingButton = Button(this).apply {`n            text = "AXION"`n            setBackgroundColor(0xFF6200EE.toInt())`n            setTextColor(0xFFFFFFFF.toInt())`n            setOnTouchListener(object : View.OnTouchListener {`n                private var initialX = 0`n                private var initialY = 0`n                private var initialTouchX = 0f`n                private var initialTouchY = 0f`n`n                override fun onTouch(v: View, event: MotionEvent): Boolean {`n                    when (event.action) {`n                        MotionEvent.ACTION_DOWN -> {`n                            initialX = params.x`n                            initialY = params.y`n                            initialTouchX = event.rawX`n                            initialTouchY = event.rawY`n                            return true`n                        }`n                        MotionEvent.ACTION_MOVE -> {`n                            params.x = initialX + (event.rawX - initialTouchX).toInt()`n                            params.y = initialY + (event.rawY - initialTouchY).toInt()`n                            windowManager.updateViewLayout(floatingButton, params)`n                            return true`n                        }`n                    }`n                    return false`n                }`n            })`n        }`n`n        windowManager.addView(floatingButton, params)`n    }`n`n    override fun onDestroy() {`n        super.onDestroy()`n        if (::floatingButton.isInitialized) {`n            windowManager.removeView(floatingButton)`n        }`n    }`n}
